  1	/**
  2	 * Tests for the outcome_summary field added to ProjectMetaSchema and RootIndexSchema (WP-002).
  3	 *
  4	 * Verifies:
  5	 * - outcome_summary accepts a non-empty string
  6	 * - outcome_summary accepts null (cleared/unset state)
  7	 * - outcome_summary is fully optional (backward compatibility — existing records without the
  8	 *   field continue to parse successfully)
  9	 */
 10	
 11	import { describe, it, expect } from 'vitest';
 12	import { ProjectMetaSchema } from '../../src/schema/project-meta.js';
 13	import { RootIndexSchema } from '../../src/schema/root-index.js';
 14	
 15	// ─── Shared base objects (no outcome_summary) ────────────────────────────────
 16	
 17	const BASE_META = {
 18	  slug: '2026-01-01-my-project',
 19	  plan_path: '/plans/2026-01-01-my-project',
 20	  status: 'READY' as const,
 21	  date_created: '2026-01-01T00:00:00.000Z',
 22	  last_updated: '2026-01-01T00:00:00.000Z',
 23	};
 24	
 25	const BASE_ROOT = {
 26	  plan_file: 'plan.md',
 27	  date_created: '2026-01-01T00:00:00.000Z',
 28	  last_updated: '2026-01-01T00:00:00.000Z',
 29	  status: 'READY' as const,
 30	  total_work_packages: 0,
 31	  pending_work_packages: 0,
 32	  work_packages: [],
 33	  project_comments: [],
 34	};
 35	
 36	// ─── ProjectMetaSchema — outcome_summary ─────────────────────────────────────
 37	
 38	describe('ProjectMetaSchema — outcome_summary field', () => {
 39	  it('accepts a non-empty string value (AC1)', () => {
 40	    const result = ProjectMetaSchema.safeParse({
 41	      ...BASE_META,
 42	      outcome_summary: 'Implemented feature X and shipped it to production.',
 43	    });
 44	    expect(result.success).toBe(true);
 45	    if (result.success) {
 46	      expect(result.data.outcome_summary).toBe('Implemented feature X and shipped it to production.');
 47	    }
 48	  });
 49	
 50	  it('accepts null (cleared/unset state) (AC1)', () => {
 51	    const result = ProjectMetaSchema.safeParse({
 52	      ...BASE_META,
 53	      outcome_summary: null,
 54	    });
 55	    expect(result.success).toBe(true);
 56	    if (result.success) {
 57	      expect(result.data.outcome_summary).toBeNull();
 58	    }
 59	  });
 60	
 61	  it('accepts absent field — backward compatibility (AC1, AC5)', () => {
 62	    const result = ProjectMetaSchema.safeParse(BASE_META);
 63	    expect(result.success).toBe(true);
 64	    if (result.success) {
 65	      expect(result.data.outcome_summary).toBeUndefined();
 66	    }
 67	  });
 68	
 69	  it('rejects a number', () => {
 70	    const result = ProjectMetaSchema.safeParse({
 71	      ...BASE_META,
 72	      outcome_summary: 42,
 73	    });
 74	    expect(result.success).toBe(false);
 75	  });
 76	
 77	  it('rejects a boolean', () => {
 78	    const result = ProjectMetaSchema.safeParse({
 79	      ...BASE_META,
 80	      outcome_summary: true,
 81	    });
 82	    expect(result.success).toBe(false);
 83	  });
 84	
 85	  it('rejects an object', () => {
 86	    const result = ProjectMetaSchema.safeParse({
 87	      ...BASE_META,
 88	      outcome_summary: { text: 'hello' },
 89	    });
 90	    expect(result.success).toBe(false);
 91	  });
 92	});
 93	
 94	// ─── RootIndexSchema — outcome_summary ───────────────────────────────────────
 95	
 96	describe('RootIndexSchema — outcome_summary field', () => {
 97	  it('accepts a non-empty string value (AC2)', () => {
 98	    const result = RootIndexSchema.safeParse({
 99	      ...BASE_ROOT,
100	      outcome_summary: 'Delivered the repository context feature end-to-end.',

101	    });
102	    expect(result.success).toBe(true);
103	    if (result.success) {
104	      expect(result.data.outcome_summary).toBe('Delivered the repository context feature end-to-end.');
105	    }
106	  });
107	
108	  it('accepts null (cleared/unset state) (AC2)', () => {
109	    const result = RootIndexSchema.safeParse({
110	      ...BASE_ROOT,
111	      outcome_summary: null,
112	    });
113	    expect(result.success).toBe(true);
114	    if (result.success) {
115	      expect(result.data.outcome_summary).toBeNull();
116	    }
117	  });
118	
119	  it('accepts absent field — backward compatibility (AC2, AC5)', () => {
120	    const result = RootIndexSchema.safeParse(BASE_ROOT);
121	    expect(result.success).toBe(true);
122	    if (result.success) {
123	      expect(result.data.outcome_summary).toBeUndefined();
124	    }
125	  });
126	
127	  it('rejects a number', () => {
128	    const result = RootIndexSchema.safeParse({
129	      ...BASE_ROOT,
130	      outcome_summary: 99,
131	    });
132	    expect(result.success).toBe(false);
133	  });
134	
135	  it('rejects a boolean', () => {
136	    const result = RootIndexSchema.safeParse({
137	      ...BASE_ROOT,
138	      outcome_summary: false,
139	    });
140	    expect(result.success).toBe(false);
141	  });
142	});

